est_time = 128;
M=csvread('tptdata.csv');
T = length(M);
save('tptdata1.mat','M')
load Data_USEconModel;
pcecret = price2ret(DataTable.PCEC);
coeret = price2ret(DataTable.COE);
Mdl = arima('Constant',6,'D',0,'Seasonality',60,...
 'MALags',1,'SMALags',15);
EstMdl = estimate(Mdl,M);
[yF, yMSE] = forecast(EstMdl,est_time,M);
upper = yF + 1.96*sqrt(yMSE);
lower = yF - 1.96*sqrt(yMSE);
figure
plot(M, 'color',[.75 .75 .75]);
hold on
h1 = plot(T+1:T+128,yF,'r','LineWidth',2);
h2 = plot(T+1:T+128,upper,'k--','LineWidth',1.5);
h3 = plot(T+1:T+128,lower,'k--','LineWidth',1.5);
xlim([0,T+128]);
title('Throughput Forecast and 95% Forecast Interval')
legend([h1,h2],'Forecast','95% Interval','Location','SouthEast');
hold off
[그림 35] ARIMA 모델을 이용한 네트워크 전송률(throughput) 예측 코드
- ARIMA 기반 학습을 통한 채널 예측 알고리즘의 최적화
Ÿ [그림 36]에서 시간에 따른 네트워크 전송률의 데이터 파일(‘tptdata.csv’) 또는 
시선예측 데이터 파일(‘eyemovedata.csv’)을 MATLAB에서 읽은 후 이를 
MATLAB 전용 파일 포맷인 ‘.mat’로 변환함. Ÿ ARIMA 모델의 자동회귀 차수는 [그림 11]에서와 같이 ‘polyfit’, ‘polyval’ 
함수를 사용하면 예측할 수 있음.
국가연구개발 보고서원문 성과물 전담기관인 한국과학기술정보연구원에서 가공·서비스 하는 연구보고서는 동의 없이 상업적 및 기타 영리목적으로 사용할 수 없습니다.
